import{_ as a,o as r,c as t,ae as s}from"./chunks/framework.Dn6zxbF8.js";const m=JSON.parse('{"title":"Linear: hierarchy, audiences, and access","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/1917971986/references/linear.md","filePath":"adrs/1917971986/references/linear.md"}'),n={name:"adrs/1917971986/references/linear.md"};function i(o,e,l,c,p,d){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="linear-hierarchy-audiences-and-access" tabindex="-1">Linear: hierarchy, audiences, and access <a class="header-anchor" href="#linear-hierarchy-audiences-and-access" aria-label="Permalink to &quot;Linear: hierarchy, audiences, and access&quot;">​</a></h1><p>Verified against primary documentation on 2026-10-10.</p><h2 id="hierarchy" tabindex="-1">Hierarchy <a class="header-anchor" href="#hierarchy" aria-label="Permalink to &quot;Hierarchy&quot;">​</a></h2><p>A Workspace is the home for all data belonging to one company: issues, teams, and every other concept in Linear live inside it, and Linear&#39;s documentation recommends that an organization stay within a single workspace rather than split across several. (<a href="https://linear.app/docs/workspaces" target="_blank" rel="noreferrer">Workspaces</a>)</p><p>Teams are the primary organizing unit beneath a workspace. Teams can be nested as sub-teams, with a parent team selected under Settings &gt; Team Hierarchy, and nesting can go up to five levels deep on the Enterprise plan; a member of a sub-team automatically has access to its parent team. Members of a sub-team must also be members of the parent team. (<a href="https://linear.app/docs/sub-teams" target="_blank" rel="noreferrer">Sub-teams</a>)</p><p>Projects group issues toward a shared, dated outcome and are not confined to one team: a project can be shared across multiple teams, with one team designated as the project&#39;s lead team, which determines the project&#39;s available statuses, while the other teams contribute to it. Initiatives sit above projects, grouping multiple projects toward a broader strategic effort. Issues are the fundamental unit of work and belong to a team. (<a href="https://linear.app/docs/projects" target="_blank" rel="noreferrer">Projects</a>; <a href="https://linear.app/docs/conceptual-model" target="_blank" rel="noreferrer">Conceptual model</a>)</p><h2 id="governance-and-work" tabindex="-1">Governance and work <a class="header-anchor" href="#governance-and-work" aria-label="Permalink to &quot;Governance and work&quot;">​</a></h2><p>Workspace-level settings, meaning general configuration, security (including SAML and login-method restrictions), billing, member administration, and audit-facing features, sit at Settings &gt; Administration, reachable only by Admins and Owners. (<a href="https://linear.app/docs/members-roles" target="_blank" rel="noreferrer">Members and roles</a>)</p><p>Work, meaning teams, issues, projects, and initiatives, is created and used below that administrative layer. A Workspace Owner role, available only on the Enterprise plan, carries full administrative control including billing, security, audit logs, workspace exports, and OAuth application approvals; the Admin role manages routine workspace operations such as member roles and suspensions without that sensitive access. (<a href="https://linear.app/docs/members-roles" target="_blank" rel="noreferrer">Members and roles</a>)</p><h2 id="audiences-and-visibility" tabindex="-1">Audiences and visibility <a class="header-anchor" href="#audiences-and-visibility" aria-label="Permalink to &quot;Audiences and visibility&quot;">​</a></h2><p>Linear names Member, Admin, Owner (Enterprise only), and Guest (Business and Enterprise plans) as roles, each scoped to the whole workspace rather than to individual teams. There is no separate &quot;public&quot; audience for a team or project; access is granted through team membership. (<a href="https://linear.app/docs/members-roles" target="_blank" rel="noreferrer">Members and roles</a>)</p><p>Teams can be made private. A private team&#39;s issues are visible only to its members, and people outside the team cannot see those issues through normal browsing or mention non-members on them. (<a href="https://linear.app/docs/private-teams" target="_blank" rel="noreferrer">Private teams</a>)</p><p>Projects inherit their audience from the teams attached to them. Custom views created inside a project are accessible to anyone with access to the project, and workspace-level views are accessible to every workspace member. (<a href="https://linear.app/docs/projects" target="_blank" rel="noreferrer">Projects</a>)</p><h2 id="narrowing-below-a-parent" tabindex="-1">Narrowing below a parent <a class="header-anchor" href="#narrowing-below-a-parent" aria-label="Permalink to &quot;Narrowing below a parent&quot;">​</a></h2><p>A team created as private narrows visibility below whatever the workspace default would otherwise be: its issues and, by extension, any project scoped to it, are hidden from non-members. (<a href="https://linear.app/docs/private-teams" target="_blank" rel="noreferrer">Private teams</a>)</p><p>A project created under a private team is visible to that team&#39;s members only. If the same project is later shared with a public team, the project becomes visible to the public team&#39;s members, but the private team&#39;s name and its issues do not become visible to people who are not members of the private team: sharing widens the project&#39;s audience without undoing the private team&#39;s own limit. (<a href="https://linear.app/docs/private-teams" target="_blank" rel="noreferrer">Private teams</a>)</p><p>Linear does not document a way for a sub-team to narrow membership below its parent team: the documentation states members of a sub-team must also be members of the parent team, which is an inherited requirement rather than a narrowing option. (<a href="https://linear.app/docs/sub-teams" target="_blank" rel="noreferrer">Sub-teams</a>)</p><h2 id="ceilings-from-above" tabindex="-1">Ceilings from above <a class="header-anchor" href="#ceilings-from-above" aria-label="Permalink to &quot;Ceilings from above&quot;">​</a></h2><p>Workspace Admins can require specific login methods for all members under Settings &gt; Administration &gt; Security, and when SAML is enabled for the workspace, members on SAML-approved domains are required to log in through SAML by default, with an option to allow non-SAML logins only for other domains (for example contractors). Owners and Admins retain the ability to log in through other methods so they are not locked out. (<a href="https://linear.app/docs/login-methods" target="_blank" rel="noreferrer">Login methods</a>; <a href="https://linear.app/docs/saml-and-access-control" target="_blank" rel="noreferrer">SAML and access control</a>)</p><p>Once SAML is enabled, admins can additionally prevent non-admins from creating new Linear workspaces using an email credential on the claimed domain, which Linear frames as a way to keep all of a company&#39;s work consolidated in a single workspace. This ceiling is opt-in: it only applies once SAML has been turned on and the option enabled. (<a href="https://linear.app/docs/saml-and-access-control" target="_blank" rel="noreferrer">SAML and access control</a>)</p><h2 id="discovery-versus-access" tabindex="-1">Discovery versus access <a class="header-anchor" href="#discovery-versus-access" aria-label="Permalink to &quot;Discovery versus access&quot;">​</a></h2><p>On the Enterprise plan, a workspace Owner cannot see a private team&#39;s issues until joining that team; on other paid plans, workspace Admins can view that a private team exists from Settings but must explicitly join it before they can see its issues. This gives private teams a visible-but-inaccessible state for admins rather than full invisibility. For ordinary members outside the team, private team issues are not discoverable through normal browsing. (<a href="https://linear.app/docs/private-teams" target="_blank" rel="noreferrer">Private teams</a>)</p><p>Guests only see the teams they have been explicitly added to and cannot see workspace-wide features such as workspace views, customer requests, or initiatives; only workspace admins can add a guest. (<a href="https://linear.app/docs/members-roles" target="_blank" rel="noreferrer">Members and roles</a>)</p><h2 id="small-customers" tabindex="-1">Small customers <a class="header-anchor" href="#small-customers" aria-label="Permalink to &quot;Small customers&quot;">​</a></h2><p>On the Free plan, all users are automatically Admins, so a small customer never has to assign a separate administrative role before managing their own workspace. (<a href="https://linear.app/docs/members-roles" target="_blank" rel="noreferrer">Members and roles</a>)</p><p>A new workspace comes with a default team created automatically, named after the workspace, so a small customer can start filing issues without first creating a team. (<a href="https://linear.app/docs/workspaces" target="_blank" rel="noreferrer">Workspaces</a>)</p><p>Sub-teams, Guests, SAML, and the Workspace Owner role are gated to Business or Enterprise plans, so a small customer on the Free or Standard plan never encounters that structure. (<a href="https://linear.app/docs/members-roles" target="_blank" rel="noreferrer">Members and roles</a>; <a href="https://linear.app/docs/sub-teams" target="_blank" rel="noreferrer">Sub-teams</a>)</p><h2 id="consolidation" tabindex="-1">Consolidation <a class="header-anchor" href="#consolidation" aria-label="Permalink to &quot;Consolidation&quot;">​</a></h2><p>Linear does not document a merge operation between two existing workspaces. The documented path for combining data is Linear-to-Linear import: an admin account common to both workspaces runs an import under Settings &gt; Administration &gt; Import/Export, choosing which teams to bring in and how to map members. Imported data includes issue fields, comments, projects, initiatives, team templates, dashboards, and documents, but saved view preferences, favorites, drafts, integrations, webhooks, OAuth clients, API keys, and billing do not transfer, and the destination workspace keeps its own URL and billing. This is a one-time data copy into a receiving workspace, not a merge of two workspaces into one. (<a href="https://linear.app/docs/linear-to-linear" target="_blank" rel="noreferrer">Linear to Linear import</a>)</p><p>Separately, Linear documents that multiple workspaces can exist under one user account, each with its own separate member list and billing. (<a href="https://linear.app/docs/workspaces" target="_blank" rel="noreferrer">Workspaces</a>)</p><h2 id="relevance-to-this-adr" tabindex="-1">Relevance to this ADR <a class="header-anchor" href="#relevance-to-this-adr" aria-label="Permalink to &quot;Relevance to this ADR&quot;">​</a></h2><ul><li>Linear&#39;s Workspace matches this ADR&#39;s Organization-as-root only loosely: Linear&#39;s workspace is explicitly where &quot;all data&quot; lives, including work, rather than a governance-only root with work pushed down into children, so Linear does not separate a governing root from a working layer the way this ADR does.</li><li>Linear&#39;s Team, especially with sub-teams nested up to five levels, maps closely onto this ADR&#39;s Folder: a freely nestable position below the top level that groups work and that a project or issue attaches through. Linear&#39;s requirement that sub-team members also be parent-team members is a form of inherited grant this ADR&#39;s model would describe as a parent not narrowing membership for its child.</li><li>Linear&#39;s private-team visibility rule, where a shared project stays invisible to the private team&#39;s non-members even after being shared with a public team, is a concrete, sourced example of a parent&#39;s limit capping a descendant exactly as this ADR describes.</li><li>Linear&#39;s SAML-gated workspace-creation restriction is a precise instance of &quot;root ceilings are opt-in per policy&quot;: the cap exists only once an admin enables SAML and the restriction together.</li><li>Linear diverges from this ADR on consolidation: this ADR requires an explicit cross-tenant migration that re-homes a workspace and its descendants intact, while Linear&#39;s only documented path is a partial, team-by-team data import that leaves settings, integrations, and billing behind, closer to a one-time copy than a re-homing migration.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li><a href="https://linear.app/docs/workspaces" target="_blank" rel="noreferrer">Workspaces</a></li><li><a href="https://linear.app/docs/sub-teams" target="_blank" rel="noreferrer">Sub-teams</a></li><li><a href="https://linear.app/docs/conceptual-model" target="_blank" rel="noreferrer">Conceptual model</a></li><li><a href="https://linear.app/docs/projects" target="_blank" rel="noreferrer">Projects</a></li><li><a href="https://linear.app/docs/private-teams" target="_blank" rel="noreferrer">Private teams</a></li><li><a href="https://linear.app/docs/members-roles" target="_blank" rel="noreferrer">Members and roles</a></li><li><a href="https://linear.app/docs/login-methods" target="_blank" rel="noreferrer">Login methods</a></li><li><a href="https://linear.app/docs/saml-and-access-control" target="_blank" rel="noreferrer">SAML and access control</a></li><li><a href="https://linear.app/docs/linear-to-linear" target="_blank" rel="noreferrer">Linear to Linear import</a></li></ul>',34)])])}const u=a(n,[["render",i]]);export{m as __pageData,u as default};
